def count_paths(H: int, W: int, K: int, grid: list[str]) -> int:
    """Count oriented paths of K moves through distinct empty grid cells.

    Each step moves up, down, left, or right. Every empty cell is considered
    as a starting point, and no cell may be visited twice in a path.
    """
    cells = [(r, c) for r in range(H) for c in range(W) if grid[r][c] == '.']
    if len(cells) <= K:
        return 0

    indices = {cell: i for i, cell in enumerate(cells)}
    neighbors = [[] for _ in cells]
    for i, (r, c) in enumerate(cells):
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            j = indices.get((r + dr, c + dc))
            if j is not None:
                neighbors[i].append(j)

    visited = [False] * len(cells)

    def search(vertex, remaining):
        if remaining == 0:
            return 1
        total = 0
        for nxt in neighbors[vertex]:
            if not visited[nxt]:
                visited[nxt] = True
                total += search(nxt, remaining - 1)
                visited[nxt] = False
        return total

    answer = 0
    for start in range(len(cells)):
        visited[start] = True
        answer += search(start, K)
        visited[start] = False
    return answer

