from functools import lru_cache
from math import gcd


@lru_cache(maxsize=None)
def _nonzero_completions(length: int, digit_sum: int, divisor: int) -> int:
    """Count nonzero digit strings with this sum and required product factor."""
    if digit_sum < length or digit_sum > 9 * length:
        return 0
    if length == 0:
        return int(digit_sum == 0 and divisor == 1)
    return sum(
        _nonzero_completions(
            length - 1, digit_sum - digit, divisor // gcd(divisor, digit)
        )
        for digit in range(1, 10)
    )


def _count_up_to(bound: int) -> int:
    if bound <= 0:
        return 0
    digits = [int(digit) for digit in str(bound)]
    size = len(digits)

    # Every positive number containing a zero has product zero and qualifies.
    nonzero_count = sum(9 ** length for length in range(1, size))
    for index, digit in enumerate(digits):
        nonzero_count += max(0, digit - 1) * 9 ** (size - index - 1)
        if digit == 0:
            break
    else:
        nonzero_count += 1
    answer = bound - nonzero_count

    # A product of nonzero decimal digits has no prime factors beyond 2,3,5,7.
    for target_sum in range(1, 9 * size + 1):
        factor = target_sum
        for prime in (2, 3, 5, 7):
            while factor % prime == 0:
                factor //= prime
        if factor != 1:
            continue

        for length in range(1, size):
            answer += _nonzero_completions(length, target_sum, target_sum)

        remaining_sum = target_sum
        divisor = target_sum
        for index, upper in enumerate(digits):
            remaining_length = size - index - 1
            for digit in range(1, upper):
                answer += _nonzero_completions(
                    remaining_length,
                    remaining_sum - digit,
                    divisor // gcd(divisor, digit),
                )
            if upper == 0:
                break
            remaining_sum -= upper
            divisor //= gcd(divisor, upper)
        else:
            answer += int(remaining_sum == 0 and divisor == 1)

    return answer


def count_beautiful_numbers(l: int, r: int) -> int:
    """Count beautiful positive integers in the inclusive range [l, r].

    A number is beautiful when its digit product is divisible by its digit sum.
    The bounds satisfy 1 <= l <= r < 10**9.

    >>> count_beautiful_numbers(10, 20)
    2
    >>> count_beautiful_numbers(1, 15)
    10
    >>> count_beautiful_numbers(4, 4)
    1
    """
    return _count_up_to(r) - _count_up_to(l - 1)

