from typing import List, Tuple


def min_sensor_cost(n: int, sections: List[int], sensor1: Tuple[int, int, int], sensor2: Tuple[int, int, int]) -> int:
    """Return the minimum cost to cover each section, or -1 if impossible.

    A sensor belongs to one section. Coverage may exceed that section's length.
    Each sensor tuple contains its coverage length, cost, and total available count.
    """
    l1, c1, k1 = sensor1
    l2, c2, k2 = sensor2

    # No section benefits from more sensors of one type than would cover it
    # completely using that type alone.
    k1 = min(k1, sum((d + l1 - 1) // l1 for d in sections))
    k2 = min(k2, sum((d + l2 - 1) // l2 for d in sections))
    if k1 > k2:
        l1, c1, k1, l2, c2, k2 = l2, c2, k2, l1, c1, k1

    # For every retained count of type 1, store the least type 2 count.
    # States dominated in both counts can never improve a later solution.
    states = [(0, 0)]
    for d in sections:
        options = []
        previous_b = k2 + 1
        first_a = max(0, (d - k2 * l2 + l1 - 1) // l1)
        last_a = min(k1, (d + l1 - 1) // l1)
        for a in range(first_a, last_a + 1):
            b = max(0, (d - a * l1 + l2 - 1) // l2)
            if b < previous_b:
                options.append((a, b))
                previous_b = b
        if not options:
            return -1

        best = {}
        for used_a, used_b in states:
            for a, b in options:
                total_a = used_a + a
                if total_a > k1:
                    break
                total_b = used_b + b
                if total_b <= k2 and total_b < best.get(total_a, k2 + 1):
                    best[total_a] = total_b
        states = []
        previous_b = k2 + 1
        for a in sorted(best):
            b = best[a]
            if b < previous_b:
                states.append((a, b))
                previous_b = b
        if not states:
            return -1

    return min(a * c1 + b * c2 for a, b in states)

