def count_paths(H: int, W: int, K: int, grid: list[str]) -> int:
    """Count ordered simple paths of K moves through empty grid cells.

    Each path starts at any empty cell, uses orthogonal moves, and visits
    every cell at most once. Reversing a path counts as another path.
    """
    cells = [(r, c) for r in range(H) for c in range(W) if grid[r][c] == "."]
    if len(cells) <= K:
        return 0

    index = {cell: i for i, cell in enumerate(cells)}
    neighbors = [[] for _ in cells]
    for i, (r, c) in enumerate(cells):
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            j = index.get((r + dr, c + dc))
            if j is not None:
                neighbors[i].append(j)

    visited = [False] * len(cells)

    def search(cell: int, remaining: int) -> int:
        if remaining == 0:
            return 1
        total = 0
        for nxt in neighbors[cell]:
            if not visited[nxt]:
                visited[nxt] = True
                total += search(nxt, remaining - 1)
                visited[nxt] = False
        return total

    total = 0
    for start in range(len(cells)):
        visited[start] = True
        total += search(start, K)
        visited[start] = False
    return total

