from functools import lru_cache


def count_good_integers(num1: str, num2: str, min_sum: int, max_sum: int) -> int:
    """Count integers in [num1, num2] with digit sums in [min_sum, max_sum].

    Return the count modulo 10^9 + 7. Bounds are numeric strings representing
    integers from 1 through 10^22, and 1 <= min_sum <= max_sum <= 400.

    >>> count_good_integers("1", "12", 1, 8)
    11
    >>> count_good_integers("1", "5", 1, 5)
    5
    """
    modulus = 10**9 + 7

    def count_up_to(bound: str) -> int:
        digits = tuple(map(int, bound))
        cap = min(max_sum, 9 * len(digits))

        @lru_cache(None)
        def dp(position: int, digit_sum: int, tight: bool) -> int:
            if digit_sum > cap:
                return 0
            if digit_sum + 9 * (len(digits) - position) < min_sum:
                return 0
            if position == len(digits):
                return int(min_sum <= digit_sum <= cap)

            limit = digits[position] if tight else 9
            total = 0
            for digit in range(min(limit, cap - digit_sum) + 1):
                total += dp(position + 1, digit_sum + digit,
                            tight and digit == limit)
            return total % modulus

        return dp(0, 0, True)

    # Subtract the count through the lower bound, then restore that bound
    # itself when it satisfies the requested digit-sum interval.
    lower_is_good = min_sum <= sum(map(int, num1)) <= max_sum
    return (count_up_to(num2) - count_up_to(num1) + lower_is_good) % modulus

