def count_valid_grids(H: int, W: int, grid: list[str]) -> int:
    """Count proper completions of a partially filled three-color grid.

    Every '?' is replaced by '1', '2', or '3', and edge-sharing cells
    must have different digits. Return the count modulo 998244353.
    The dimensions satisfy 1 <= H, 1 <= W, and H * W <= 200.
    """
    MOD = 998244353

    # Detect contradictory fixed clues before building any frontier states.
    for r in range(H):
        for c in range(W):
            digit = grid[r][c]
            if digit == '?':
                continue
            if r and grid[r - 1][c] == digit:
                return 0
            if c and grid[r][c - 1] == digit:
                return 0

    # The smaller dimension is at most 14 under the area bound.
    if W > H:
        grid = [''.join(grid[r][c] for r in range(H)) for c in range(W)]
        H, W = W, H

    # Two bits per frontier cell; zero denotes a not-yet-filled cell.
    # Oldest (upper neighbor) is at the high end; newest is at the low end.
    top_shift = 2 * (W - 1)
    tail_mask = (1 << top_shift) - 1
    choices = {
        (upper, left): tuple(d for d in (1, 2, 3)
                             if d != upper and d != left)
        for upper in range(4) for left in range(4)
    }
    dp = {0: 1}
    for r in range(H):
        for c in range(W):
            clue = grid[r][c]
            fixed = int(clue) if clue != '?' else 0
            next_dp = {}
            for state, count in dp.items():
                upper = state >> top_shift
                left = state & 3 if c else 0
                base = (state & tail_mask) << 2
                if fixed:
                    if fixed == upper or fixed == left:
                        continue
                    new_state = base | fixed
                    next_dp[new_state] = (next_dp.get(new_state, 0) + count) % MOD
                else:
                    for digit in choices[upper, left]:
                        new_state = base | digit
                        next_dp[new_state] = (next_dp.get(new_state, 0) + count) % MOD
            dp = next_dp
            if not dp:
                return 0
    return sum(dp.values()) % MOD

