def sum_good_sequence_scores(n: int, a: list[int]) -> int:
    """Sum products of positive integer sequences with the prescribed reduced ratios.

    For each prime, adjacent exponents differ by its exponent in a[i].
    Normalize the exponent walk to have minimum zero, enforcing gcd(S) = 1.
    Prime exponent walks are independent, so their weighted sums multiply.
    """
    mod = 998244353
    exponents = {}
    for i, value in enumerate(a):
        p = 2
        while p * p <= value:
            if value % p == 0:
                count = 0
                while value % p == 0:
                    value //= p
                    count += 1
                if p not in exponents:
                    exponents[p] = [0] * (n - 1)
                exponents[p][i] = count
            p += 1
        if value > 1:
            if value not in exponents:
                exponents[value] = [0] * (n - 1)
            exponents[value][i] = 1

    answer = 1
    for p, steps in exponents.items():
        total = sum(steps)
        powers = [1] * (total + 1)
        for j in range(1, total + 1):
            powers[j] = powers[j - 1] * p % mod

        # dp[h] sums scores of normalized prefixes whose last exponent is h.
        dp = [1]
        for i, step in enumerate(steps, 1):
            if step == 0:
                dp = [weight * powers[h] % mod
                      for h, weight in enumerate(dp)]
                continue
            nxt = [0] * (len(dp) + step)
            # If the downward step crosses zero, all i previous exponents
            # increase by step-h when we normalize the extended prefix.
            shift_base = pow(p, i, mod)
            shifts = [1] * (step + 1)
            for j in range(1, step + 1):
                shifts[j] = shifts[j - 1] * shift_base % mod
            for h, weight in enumerate(dp):
                up = h + step
                nxt[up] = (nxt[up] + weight * powers[up]) % mod
                if h >= step:
                    down = h - step
                    nxt[down] = (nxt[down] + weight * powers[down]) % mod
                else:
                    nxt[0] = (nxt[0] + weight * shifts[step - h]) % mod
            dp = nxt
        answer = answer * (sum(dp) % mod) % mod
    return answer

