from functools import lru_cache


@lru_cache(maxsize=None)
def _beautiful_suffix(remaining: int, digit_sum: int, product: int) -> int:
    """Count unrestricted suffixes; a zero sum means no digit has started."""
    if remaining == 0:
        return int(digit_sum > 0 and product % digit_sum == 0)

    if digit_sum:
        # A genuine zero digit makes every following completion beautiful.
        total = 10 ** (remaining - 1)
    else:
        # Leading padding zeroes do not belong to the number.
        total = _beautiful_suffix(remaining - 1, 0, 1)
    for digit in range(1, 10):
        total += _beautiful_suffix(
            remaining - 1, digit_sum + digit, product * digit
        )
    return total


def _beautiful_up_to(bound: int) -> int:
    if bound <= 0:
        return 0

    digits = str(bound)
    total = 0
    digit_sum = 0
    product = 1
    for position, char in enumerate(digits):
        limit = int(char)
        remaining = len(digits) - position - 1
        for digit in range(limit):
            if digit == 0 and digit_sum:
                total += 10 ** remaining
            else:
                total += _beautiful_suffix(
                    remaining, digit_sum + digit, product * (digit or 1)
                )

        if limit == 0 and digit_sum:
            # The equal prefix now contains zero. All suffixes up to the
            # bound are valid, including a suffix consisting only of zeroes.
            return total + bound % (10 ** remaining) + 1
        digit_sum += limit
        product *= limit or 1

    return total + int(product % digit_sum == 0)


def count_beautiful_numbers(l: int, r: int) -> int:
    """Count the number of beautiful numbers in the range [l, r] inclusive.

    A positive integer is called beautiful if the product of its digits is
    divisible by the sum of its digits.

    Args:
        l: The lower bound of the range (inclusive)
        r: The upper bound of the range (inclusive)

    Returns:
        The count of beautiful numbers in the range [l, r]

    Constraints:
        1 <= l <= r < 10^9

    >>> count_beautiful_numbers(10, 20)
    2
    >>> count_beautiful_numbers(1, 15)
    10
    >>> count_beautiful_numbers(4, 4)
    1
    """
    return _beautiful_up_to(r) - _beautiful_up_to(l - 1)

