def min_operations_to_rearrange(n: int, s: str, t: str) -> int:
    """Return the minimum adjacent-pair moves transforming s into t.

    The n stones occupy cells 1 through n, followed by two empty cells.
    A move places two adjacent stones into the empty cells, preserving order.
    The target also has its empty cells in the final two positions.
    Return -1 when the target cannot be reached. 2 <= n <= 14.
    """
    if s == t:
        return 0
    if s.count('W') != t.count('W'):
        return -1

    # White stones use set bits; black stones and empty cells use zero bits.
    # Store the start of the empty pair in the low four bits of each state.
    start_mask = sum(1 << i for i, color in enumerate(s) if color == 'W')
    target_mask = sum(1 << i for i, color in enumerate(t) if color == 'W')
    start = (start_mask << 4) | n
    target = (target_mask << 4) | n

    # A source pair must be disjoint from the two empty cells.
    sources = [
        tuple(i for i in range(n + 1) if i + 1 < hole or i > hole + 1)
        for hole in range(n + 1)
    ]
    frontier = {start}
    opposite_frontier = {target}
    distances = {start: 0}
    opposite_distances = {target: 0}

    while frontier and opposite_frontier:
        # Expand a complete distance layer from the smaller frontier.
        if len(frontier) > len(opposite_frontier):
            frontier, opposite_frontier = opposite_frontier, frontier
            distances, opposite_distances = opposite_distances, distances

        next_frontier = set()
        for state in frontier:
            mask = state >> 4
            hole = state & 15
            next_distance = distances[state] + 1
            for source in sources[hole]:
                pair = (mask >> source) & 3
                moved_mask = mask ^ (pair << source) ^ (pair << hole)
                neighbor = (moved_mask << 4) | source
                if neighbor in distances:
                    continue
                if neighbor in opposite_distances:
                    return next_distance + opposite_distances[neighbor]
                distances[neighbor] = next_distance
                next_frontier.add(neighbor)
        frontier = next_frontier

    return -1
